const now = new Date();
const parts = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Bangkok', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', hour12: false }).formatToParts(now);
const get = (t) => parts.find((p) => p.type === t)?.value;
const hour = Number(get('hour'));
const slotHour = hour < 13 ? '07' : '19';
const slot = `${get('year')}-${get('month')}-${get('day')}T${slotHour}`;
return [{ json: { slot } }];
